insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'ms_dance3_v1'
from (values
('117.207.b.1.A',3,'Eighth-grade dancers cross the floor in a diagonal line, adjusting speed so nobody collides. This builds:','["group spatial awareness", "script memory", "ticket sales skill", "set design skill"]'::jsonb,0,'Adjusting to others in space builds group spatial awareness.','original'),
('117.207.b.1.A',3,'Sensing the exact height of your leg in an extension with your eyes closed relies on:','["stage lights", "kinesthetic sense", "a metronome", "a mirror only"]'::jsonb,1,'Kinesthetic sense tells the body where it is without sight.','original'),
('117.207.b.1.B',4,'A dancer needs to distinguish a healthy habit from a harmful one. Which is the harmful habit?','["eating balanced meals", "stretching gently", "dancing through sharp pain", "resting after a long class"]'::jsonb,2,'Dancing through sharp pain risks injury.','original'),
('117.207.b.1.B',3,'Which statement best separates wellness from simply being busy?','["Wellness means practicing nonstop.", "Wellness only means weight.", "Wellness means avoiding all rest.", "Wellness balances activity, rest, nutrition and mental health."]'::jsonb,3,'Wellness is balanced and holistic.','original'),
('117.207.b.1.C',4,'Implementing body science, a dancer lowers her heels fully after a rise to:','["protect the Achilles tendon and calf", "change the music", "shorten the dance", "add noise to the floor"]'::jsonb,0,'Landing through the foot protects the lower leg.','original'),
('117.207.b.1.C',3,'A dancer who uses the term ''port de bras'' correctly is describing:','["a floor roll", "the movement and carriage of the arms", "a turn only", "a jump"]'::jsonb,1,'Port de bras means carriage of the arms.','original'),
('117.207.b.1.D',3,'Developing a phrase by changing from a low level to a high level, a wide shape to a narrow shape, and fast to slow shows work with space and:','["ticket price", "lighting only", "time and energy", "costume only"]'::jsonb,2,'Elements combine in developed phrases.','original'),
('117.207.b.1.D',4,'To develop energy qualities, a choreographer might ask dancers to shift from percussive to sustained movement. This changes the:','["costume fabric", "seat number", "floor size", "quality of force"]'::jsonb,3,'Percussive versus sustained are energy qualities.','original'),
('117.207.b.2.A',3,'Applying alignment principles, a dancer in a turn keeps her:','["core engaged and head level", "ribs flared", "weight behind the heels", "head tilted"]'::jsonb,0,'A level head and engaged core support turns.','original'),
('117.207.b.2.A',4,'A student correcting her posture sees her pelvis tilted forward. Applying a principle of alignment, she should:','["lock her knees", "bring the pelvis to neutral", "lean backward", "tuck her chin more"]'::jsonb,1,'A neutral pelvis helps alignment.','original'),
('117.207.b.2.B',3,'A choreographer uses canon, where dancers perform the same phrase beginning at different times. This technique creates:','["a stalled piece", "a silent stage", "a layered, rippling effect", "a single solo"]'::jsonb,2,'Canon staggers the same movement.','original'),
('117.207.b.2.B',4,'Demonstrating knowledge of a choreographic process, a student starts with a prompt, explores ideas, selects, structures and then:','["throws it away", "sells it", "skips the plan", "refines the work"]'::jsonb,3,'Refining follows selecting and structuring.','original'),
('117.207.b.2.C',3,'Creating a movement study with a 3/4 pulse and diagonal pathways uses:','["rhythm and spatial directions together", "only audience notes", "only lighting", "only costume ideas"]'::jsonb,0,'The study combines rhythm and direction.','original'),
('117.207.b.2.C',4,'A movement study that begins in a corner and travels through the center shows a deliberate use of:','["punctuation", "floor pathway", "pronunciation", "tuition"]'::jsonb,1,'Pathways are planned routes through space.','original'),
('117.207.b.2.D',3,'To design a duet that expresses tension, partners might use:','["gentle skipping", "relaxed rolling", "sudden shifts, close proximity and held eye contact", "slow gentle waves"]'::jsonb,2,'Design choices convey emotion.','original'),
('117.207.b.2.D',4,'A group designs a dance expressing the idea of change. Which movement choice most clearly supports it?','["exiting the stage", "standing still", "repeating one pose", "gradually transforming one shape into another"]'::jsonb,3,'Transformations illustrate change.','original'),
('117.207.b.3.A',3,'Applying a musical theatre style, dancers often combine movement with:','["acting, singing and storytelling", "weight lifting", "long division", "silence and stillness only"]'::jsonb,0,'Musical theatre blends several arts.','original'),
('117.207.b.3.A',3,'A student applies the tap style by:','["staying silent on the floor", "using foot rhythms to create percussive sounds", "only jumping", "avoiding rhythm"]'::jsonb,1,'Tap makes rhythm with the feet.','original'),
('117.207.b.3.B',3,'To express emotion in performance, a dancer may combine facial focus with:','["a ticket", "a timer", "the quality of her movement", "a printed program"]'::jsonb,2,'Emotion is expressed through face and movement.','original'),
('117.207.b.3.B',4,'When dancers perform with the intent to communicate, they should maintain:','["quick exits", "low energy always", "hidden faces", "commitment and focus throughout the piece"]'::jsonb,3,'Commitment communicates intent.','original'),
('117.207.b.3.C',4,'Evaluating how a lighting plan changes the mood of a dance means judging the use of:','["technology in the performance", "a recess schedule", "a math worksheet", "a locker"]'::jsonb,0,'Lighting design is performance technology.','original'),
('117.207.b.3.C',4,'A choreographer evaluates a rehearsal video and notes that two dancers lost the beat. The evaluation is mostly about:','["costume color", "timing and accuracy", "ticket sales", "seat comfort"]'::jsonb,1,'Video helps evaluate timing.','original'),
('117.207.b.3.D',2,'Practicing a cool-down regularly is important because it:','["erases technique", "makes the next class harder", "reduces soreness and supports recovery", "adds injury risk"]'::jsonb,2,'Cool-downs reduce soreness.','original'),
('117.207.b.3.D',3,'A good conditioning routine for dancers includes building:','["only volume", "only height", "only speed", "strength, flexibility and endurance"]'::jsonb,3,'Conditioning strengthens the body for dance.','original'),
('117.207.b.4.A',4,'Comparing two folk dances from different regions, a student notices one uses circle formations and the other uses lines. This is a comparison of:','["cultural movement features", "bus routes", "lighting charts", "ticket costs"]'::jsonb,0,'Formations are features of cultural dances.','original'),
('117.207.b.4.A',4,'Contrasting a ceremonial dance with a social dance, a student sees that the ceremonial one often:','["is only for competition", "carries ritual or sacred meaning", "is never repeated", "has no steps"]'::jsonb,1,'Ceremonial dances have ritual meaning.','original'),
('117.207.b.4.B',4,'To evaluate historical dance forms, a student judges how well movements show:','["the stage paint", "the shoe brand", "the values and era of the form", "the price"]'::jsonb,2,'Evaluation connects movement to its historical context.','original'),
('117.207.b.4.B',4,'Evaluating contributions to a dance form means judging the impact of:','["the ticket office", "the theater''s roof", "the audience''s seats", "the artists who developed and taught it"]'::jsonb,3,'Contributors shape a form''s development.','original'),
('117.207.b.4.C',2,'Performing a dance from her own heritage lets a student:','["share and honor her family''s culture", "skip rehearsal", "avoid her culture", "hide the dance"]'::jsonb,0,'Heritage dances honor culture.','original'),
('117.207.b.4.C',3,'A dance performed to celebrate the local landscape would represent the dancers'':','["mailbox", "environment", "wallet", "calendar"]'::jsonb,1,'Environmental dances celebrate place.','original'),
('117.207.b.4.D',3,'A student creates a short dance for a video to share online. She is creating dance in:','["a ledger", "a printed pamphlet only", "a digital media format", "a coloring book"]'::jsonb,2,'Dance can be created for digital media.','original'),
('117.207.b.4.D',3,'Creating a dance that teaches the phases of the moon links dance to:','["a meal plan", "a hall pass", "an unrelated hobby", "another content area such as science"]'::jsonb,3,'Dance can teach content.','original'),
('117.207.b.5.A',4,'When designing criteria to evaluate a performance, a student might include:','["timing, clarity of intent and technique", "seat softness", "ticket price", "program color"]'::jsonb,0,'Criteria should be tied to performance quality.','original'),
('117.207.b.5.A',4,'Applying criteria in a peer review means:','["voting for friends", "scoring each element fairly and giving reasons", "skipping the review", "ignoring details"]'::jsonb,1,'Fair, reasoned evaluation applies criteria.','original'),
('117.207.b.5.B',3,'Creating a relationship between dance and geometry, students form shapes such as triangles with their bodies. This relates dance to:','["gardening", "cooking", "mathematics", "plumbing"]'::jsonb,2,'Shapes link dance and math.','original'),
('117.207.b.5.B',3,'Choreographing a dance about a novel''s conflict relates dance to:','["mailing", "parking", "woodworking", "literature"]'::jsonb,3,'Dance can interpret stories.','original'),
('117.207.b.5.C',4,'Comparing two American choreographers, a student notes that one favors flowing, grounded movement and the other favors sharp, angular movement. This is a comparison of:','["choreographic content", "parking", "costume weight", "ticket price"]'::jsonb,0,'Style and movement content differ across choreographers.','original'),
('117.207.b.5.C',4,'Contrasting two dance structures, a student sees that one tells a story in order while the other repeats a theme. These differ in:','["bus route", "choreographic structure", "homework", "lighting brand"]'::jsonb,1,'Narrative versus thematic structures differ.','original'),
('117.207.b.5.D',4,'Justifying an artistic decision means:','["denying it", "hiding the choice", "explaining why a choice supports the dance''s meaning", "ignoring feedback"]'::jsonb,2,'Justification gives reasons.','original'),
('117.207.b.5.D',4,'A student explains that she added a pause in her solo so the audience could feel the silence. She is justifying a decision about:','["costume tags", "parking", "ticket color", "timing and emphasis"]'::jsonb,3,'Pauses create emphasis.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
